impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let mut dp = vec![vec![-1i128; n + 1]; k + 1];
        dp[0][0] = 0;

        for i in 0..k {
            for j in 0..n {
                if dp[i][j] == -1 {
                    continue;
                }
                // Option 1: skip the current position
                if dp[i][j + 1] < dp[i][j] {
                    dp[i][j + 1] = dp[i][j];
                }
                // Option 2: take a segment starting at j
                if j + m <= n {
                    let sum = nums[j..j + m].iter().sum::<i64>() as i128;
                    if i + 1 <= k && dp[i + 1][j + m] < dp[i][j] + sum {
                        dp[i + 1][j + m] = dp[i][j] + sum;
                    }
                }
            }
        }

        let mut result = -1i128;
        for j in 0..=n {
            if dp[k][j] > result {
                result = dp[k][j];
            }
        }
        result
    }
}

